-- CheckpointsTrekking | Projeto de Dados Final | MySQL 8.0.16+
-- Banco completo: seis tabelas legadas + historico_corrida.
-- Os INSERTs originais (1.000 registros) foram mantidos sem modificacoes.
-- Executar em banco de testes: recria as tabelas deste schema.

CREATE DATABASE IF NOT EXISTS checkpoints_trekking CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE checkpoints_trekking;

SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS historico_corrida;
DROP TABLE IF EXISTS passagem;
DROP TABLE IF EXISTS participacao;
DROP TABLE IF EXISTS checkpoint;
DROP TABLE IF EXISTS equipe;
DROP TABLE IF EXISTS corrida;
DROP TABLE IF EXISTS professor;
SET FOREIGN_KEY_CHECKS = 1;

-- Corrida: data_realizacao derivada dos registros legados de passagem;
-- criado_em e total_checkpoints_previstos ficam NULL no legado quando desconhecidos.
CREATE TABLE corrida (
  id_corrida INT AUTO_INCREMENT PRIMARY KEY,
  nome VARCHAR(120) NOT NULL UNIQUE,
  data_realizacao DATE NULL,
  total_checkpoints_previstos INT NULL,
  status VARCHAR(20) NOT NULL DEFAULT 'Planejada',
  criado_em DATETIME NULL,
  CONSTRAINT chk_corrida_nome CHECK (CHAR_LENGTH(TRIM(nome)) > 0),
  CONSTRAINT chk_corrida_previstos CHECK (total_checkpoints_previstos IS NULL OR total_checkpoints_previstos > 0),
  CONSTRAINT chk_corrida_status CHECK (status IN ('Planejada','Em andamento','Concluida','Cancelada'))
) ENGINE=InnoDB;

CREATE TABLE equipe (
  id_equipe INT AUTO_INCREMENT PRIMARY KEY,
  nome VARCHAR(120) NOT NULL UNIQUE,
  CONSTRAINT chk_equipe_nome CHECK (CHAR_LENGTH(TRIM(nome)) > 0)
) ENGINE=InnoDB;

CREATE TABLE professor (
  id_professor INT AUTO_INCREMENT PRIMARY KEY,
  nome VARCHAR(120) NOT NULL UNIQUE,
  CONSTRAINT chk_professor_nome CHECK (CHAR_LENGTH(TRIM(nome)) > 0)
) ENGINE=InnoDB;

CREATE TABLE checkpoint (
  id_checkpoint INT AUTO_INCREMENT PRIMARY KEY,
  numero INT NOT NULL,
  id_corrida INT NOT NULL,
  id_professor INT NOT NULL,
  CONSTRAINT chk_checkpoint_numero CHECK (numero > 0),
  CONSTRAINT uq_checkpoint_numero_corrida UNIQUE (id_corrida, numero),
  CONSTRAINT uq_checkpoint_composto UNIQUE (id_checkpoint, id_corrida, id_professor),
  CONSTRAINT fk_checkpoint_corrida FOREIGN KEY (id_corrida) REFERENCES corrida(id_corrida) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT fk_checkpoint_professor FOREIGN KEY (id_professor) REFERENCES professor(id_professor) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB;

CREATE TABLE participacao (
  id_corrida INT NOT NULL,
  id_equipe INT NOT NULL,
  status VARCHAR(20) NOT NULL DEFAULT 'Confirmada',
  inscrito_em DATETIME NULL,
  PRIMARY KEY (id_corrida, id_equipe),
  CONSTRAINT chk_participacao_status CHECK (status IN ('Inscrita','Confirmada','Concluida','Desistente','Desclassificada','Cancelada')),
  CONSTRAINT fk_participacao_corrida FOREIGN KEY (id_corrida) REFERENCES corrida(id_corrida) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT fk_participacao_equipe FOREIGN KEY (id_equipe) REFERENCES equipe(id_equipe) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB;

-- Chaves compostas asseguram inscricao valida e responsabilidade do professor.
CREATE TABLE passagem (
  id_passagem INT AUTO_INCREMENT PRIMARY KEY,
  id_corrida INT NOT NULL,
  id_equipe INT NOT NULL,
  id_checkpoint INT NOT NULL,
  id_professor INT NOT NULL,
  momento DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uq_passagem_unica UNIQUE (id_corrida, id_equipe, id_checkpoint),
  CONSTRAINT fk_passagem_participacao FOREIGN KEY (id_corrida, id_equipe) REFERENCES participacao(id_corrida, id_equipe) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT fk_passagem_checkpoint FOREIGN KEY (id_checkpoint, id_corrida, id_professor) REFERENCES checkpoint(id_checkpoint, id_corrida, id_professor) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB;

CREATE TABLE historico_corrida (
  id_historico INT AUTO_INCREMENT PRIMARY KEY,
  id_corrida INT NOT NULL,
  status_anterior VARCHAR(20) NULL,
  status_novo VARCHAR(20) NOT NULL,
  momento DATETIME NOT NULL,
  origem VARCHAR(16) NOT NULL,
  observacao VARCHAR(180) NOT NULL,
  CONSTRAINT chk_historico_anterior CHECK (status_anterior IS NULL OR status_anterior IN ('Planejada','Em andamento','Concluida','Cancelada')),
  CONSTRAINT chk_historico_novo CHECK (status_novo IN ('Planejada','Em andamento','Concluida','Cancelada')),
  CONSTRAINT chk_historico_origem CHECK (origem IN ('Importacao','Simulacao')),
  CONSTRAINT fk_historico_corrida FOREIGN KEY (id_corrida) REFERENCES corrida(id_corrida) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB;

