-- Adaptacao do legado sem substituir seus registros.
-- A data das 40 etapas antigas e deduzida de MIN(passagem.momento).
-- Campos nao registrados na atividade antiga permanecem NULL (sem inventar historico).
UPDATE corrida c
JOIN (SELECT id_corrida, DATE(MIN(momento)) AS dia FROM passagem GROUP BY id_corrida) p
  ON p.id_corrida = c.id_corrida
SET c.data_realizacao = p.dia, c.status = 'Concluida'
WHERE c.id_corrida BETWEEN 1 AND 40;

-- Uma corrida sem passagens deve receber uma data antes de passar a ser obrigatoria.
ALTER TABLE corrida MODIFY data_realizacao DATE NOT NULL;

