-- Conferencia: a contagem por tabela deve totalizar 4.013 registros.
SELECT 'corrida' AS tabela, COUNT(*) AS registros FROM corrida
UNION ALL SELECT 'equipe', COUNT(*) FROM equipe
UNION ALL SELECT 'professor', COUNT(*) FROM professor
UNION ALL SELECT 'checkpoint', COUNT(*) FROM checkpoint
UNION ALL SELECT 'participacao', COUNT(*) FROM participacao
UNION ALL SELECT 'passagem', COUNT(*) FROM passagem
UNION ALL SELECT 'historico_corrida', COUNT(*) FROM historico_corrida;

SELECT (SELECT COUNT(*) FROM corrida) + (SELECT COUNT(*) FROM equipe) +
       (SELECT COUNT(*) FROM professor) + (SELECT COUNT(*) FROM checkpoint) +
       (SELECT COUNT(*) FROM participacao) + (SELECT COUNT(*) FROM passagem) +
       (SELECT COUNT(*) FROM historico_corrida) AS total_registros;
